function interval(from, to) {
  return (times[to] - times[from] + period) % period;
}

function keySlope(before, after, beforeSpan, afterSpan) {
  if (before * after <= 0) return 0;
  const a = 2 * afterSpan + beforeSpan;
  const b = afterSpan + 2 * beforeSpan;
  return (a + b) / (a / before + b / after);
}

function sample(track, index, time) {
  const count = times.length;
  const previous = (index + count - 1) % count;
  const next = (index + 1) % count;
  const following = (index + 2) % count;
  const beforeSpan = interval(previous, index);
  const span = interval(index, next);
  const afterSpan = interval(next, following);
  const u = (time - times[index]) / span;
  return track[index].map((a, channel) => {
    const b = track[next][channel];
    const before = (a - track[previous][channel]) / beforeSpan;
    const current = (b - a) / span;
    const after = (track[following][channel] - b) / afterSpan;
    return hermite(a, b, span * keySlope(before, current, beforeSpan, span),
      span * keySlope(current, after, span, afterSpan), u);
  });
}

