  head.position.y -= rowOffset / (100 * cosine);
  head.quaternion.setFromAxisAngle(viewNormal, -roll * radians);

  const surface = bodySurface;
  const geometry = surface.mesh.geometry;
  const position = geometry.attributes.position;
  const normal = geometry.attributes.normal;
  const color = geometry.attributes.color;
  const leftX = leftPose[2] + 4 + leftPose[8] * 0.50;
  const leftY = leftPose[3] + 15.5;
  const rightX = rightPose[2] - 20.5 + rightPose[7] * 25;
  const rightY = rightPose[3] - 1 + rightPose[7] * 52;
  const rightWidth = 12 + rightPose[7] * 21;

  for (let i = 0; i < position.count; i++) {
    const address = i * 3;
    const x = surface.positions[address];
    const y = surface.positions[address + 1];
    const z = surface.positions[address + 2];
    const nx = surface.normals[address];
    const ny = surface.normals[address + 1];
    const nz = surface.normals[address + 2];
    const row = projectedRow(y, z);
    const weight = 1 - smooth(71, 140, row);

    if (weight > 0) {
      temporary.set(x, y, z).sub(headRest).applyQuaternion(head.quaternion).add(head.position);
      position.setXYZ(i, x + weight * (temporary.x - x), y + weight * (temporary.y - y), z + weight * (temporary.z - z));
      temporary.set(nx, ny, nz).applyQuaternion(head.quaternion);
      normal.setXYZ(i, nx + weight * (temporary.x - nx), ny + weight * (temporary.y - ny), nz + weight * (temporary.z - nz));
    } else {
      position.setXYZ(i, x, y, z);
      normal.setXYZ(i, nx, ny, nz);
    }

    const col = 122 + 100 * position.getX(i);
    const posedRow = projectedRow(position.getY(i), position.getZ(i));
    const shade = 0.52 * surface.facing[i] * (
      spot(col, posedRow, leftX, leftY, 16, 24) +
      spot(col, posedRow, rightX, rightY, rightWidth, 29)
    );
    const r = surface.colors[address];
    const g = surface.colors[address + 1];
    const b = surface.colors[address + 2];
    color.setXYZ(i, r + (wingShadow.r - r) * shade, g + (wingShadow.g - g) * shade, b + (wingShadow.b - b) * shade);
  }
  position.needsUpdate = true;
  normal.needsUpdate = true;
  color.needsUpdate = true;
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();
}

function throughMiddle(start, middle, end, u) {
  return start + (end - start) * u + (middle - (start + end) * 0.5) * 4 * u * (1 - u);
}

function poseWing(surface, arm, hand, side, tipDepth, rest, pose) {
  const [topX, topRow, midX, midRow, lowX, lowRow, width, advance, reach,
    handX, handRow, handWidth, handHeight, handRoll] = pose;
  const geometry = surface.mesh.geometry;
  const position = geometry.attributes.position;
  const span = rest[5] - rest[1];

  for (let i = 0; i < position.count; i++) {
    const address = i * 3;
    const [row, center, , centerZ] = surface.rows[surface.rings[i]];
    const u = (row - rest[1]) / span;
    const dx = throughMiddle(topX - rest[0], midX - rest[2], lowX - rest[4], u);
    const dr = throughMiddle(topRow - rest[1], midRow - rest[3], lowRow - rest[5], u);

    const z = surface.positions[address + 2] + arm.position.z;
    const back = 1 - smooth(-0.16, 0.11, z - centerZ);
    const shoulder = reach * back * 4 * u * (1 - u);
    const dz = advance - 0.0028 * shoulder;
    const centerLocal = (center - 122) / 100 - arm.position.x;
    const x = centerLocal + width * (surface.positions[address] - centerLocal);
    position.setXYZ(i,
      x + (dx - side * shoulder) / 100,
      surface.positions[address + 1] - dr / (100 * cosine) + dz * tangent,
      surface.positions[address + 2] + dz
    );
  }

  position.needsUpdate = true;
  geometry.computeVertexNormals();
  geometry.computeBoundingBox();
  geometry.computeBoundingSphere();

  hand.position.copy(point(handX, handRow, tipDepth + advance)).sub(arm.position);
  hand.quaternion.setFromAxisAngle(viewNormal, -handRoll * radians);
  hand.scale.set(handWidth, handHeight, 1);
}

function render(t = 0) {
  const remainder = t % period;
  const time = remainder < 0 ? remainder + period : remainder;
  let index = 0;
  while (index + 1 < times.length && time >= times[index + 1]) index++;

  const leftPose = sample(leftKeys, index, time);
  const rightPose = sample(rightKeys, index, time);
  poseBody(sample(headKeys, index, time), leftPose, rightPose);
  poseWing(leftSurface, leftArm, leftHand, -1, 0.455, leftKeys[0], leftPose);
  poseWing(rightSurface, rightArm, rightHand, 1, 0.448, rightKeys[0], rightPose);
  renderer.render(scene, ref);
}

render(0);
